export type NotificationStatus = 'active' | 'read' | 'resolved' | 'silenced';

export type RuleType =
  | 'task_overdue'
  | 'task_at_risk'
  | 'sprint_at_risk'
  | 'license_expiring'
  | 'license_expired'
  | 'workload_imbalance'
  | 'blocked_task';

/** An in-app notification generated by the alert engine. */
export interface AppNotification {
  id: string;
  rule_type: RuleType | string;
  title: string;
  body: string;
  target_type: string;
  target_id: string | null;
  status: NotificationStatus;
  created_at: string;
}

export interface NotificationListResponse {
  data: AppNotification[];
  meta: { total: number };
}

export interface UnreadCountResponse {
  data: { count: number };
}

/** Spanish (Colombian formal) labels per rule_type. */
export const RULE_TYPE_LABELS: Record<string, string> = {
  task_overdue: 'Tarea vencida',
  task_at_risk: 'Tarea en riesgo',
  sprint_at_risk: 'Sprint en riesgo',
  license_expiring: 'Licencia por vencer',
  license_expired: 'Licencia vencida',
  workload_imbalance: 'Sobrecarga',
  blocked_task: 'Tarea bloqueada',
};
